import type { ComponentType } from 'react';
import type { CodeViewProps } from './svg-view';

/**
 * The code kinds (D-257): an SVG artifact (preview from a blob URL, or its source) and a CSV artifact (a table). Both draw inside the
 * panel's viewer bar, with its copy and download. This module is cheap; each view loads the first time its artifact opens. Other code
 * and text stay in the panel's own code block.
 */
export interface CodeKind {
  readonly match: (target: { readonly resource: { readonly path: string } }, artifact: { readonly type: string; readonly language?: string | undefined }) => boolean;
  readonly label?: string | undefined;
  /** A default viewer for a type: a host's `viewers.svg` or `viewers.code` wins over it. */
  readonly fallback: true;
  readonly load: () => Promise<{ readonly default: ComponentType<CodeViewProps> }>;
}

export const svgKind: CodeKind = {
  match: (_target, artifact) => artifact.type === 'svg',
  fallback: true,
  load: () => import('./svg-view').then(module => ({ default: module.SvgView })),
};

export const csvKind: CodeKind = {
  match: (_target, artifact) => artifact.type === 'code' && artifact.language === 'csv',
  fallback: true,
  load: () => import('./csv-table').then(module => ({ default: module.CsvView })),
};

'use client';

import { useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { CodeXmlIcon, EyeIcon } from '../_shared/icons';
import { CodeBlock } from '../pi-chat/code-block';
import { ViewerToggle } from '../viewer-frame/viewer-frame';
import { useViewerText } from '../viewer-frame/viewer-window';

/** What the code kinds' views read of the panel's kind props (structurally `ArtifactKindViewProps` of pi-artifacts). */
export interface CodeViewProps {
  readonly text: string;
  readonly artifact: { readonly title: string };
  /** The panel bar's controls slot (the preview and source toggle goes there). */
  readonly setControls?: ((controls: ReactNode) => void) | undefined;
}

/** An SVG artifact: a preview, or its source. The preview is an image from a blob URL: it never becomes markup in this page, so its scripts cannot run. */
export function SvgView({ text, artifact, setControls }: CodeViewProps) {
  const { labels } = useViewerText();
  const [mode, setMode] = useState<'preview' | 'source'>('preview');
  const url = useMemo(() => URL.createObjectURL(new Blob([text], { type: 'image/svg+xml' })), [text]);
  useEffect(() => () => URL.revokeObjectURL(url), [url]);
  useEffect(() => {
    setControls?.(<ViewerToggle label={labels.view} value={mode} onChange={setMode} options={[
      { id: 'preview', label: labels.preview, text: labels.preview, icon: <EyeIcon className="size-4" aria-hidden="true" />, testId: 'artifact-mode' },
      { id: 'source', label: labels.source, text: labels.source, icon: <CodeXmlIcon className="size-4" aria-hidden="true" />, testId: 'artifact-mode' }]} />);
    return () => setControls?.(undefined);
  }, [setControls, mode, labels.view, labels.preview, labels.source]);
  return mode === 'preview'
    ? <div className="boring-viewer-checker flex h-full min-h-0 items-center justify-center overflow-auto p-6"><img data-testid="artifact-svg" src={url} alt={artifact.title} className="max-h-full max-w-full" /></div>
    : <div className="min-h-0 p-3"><CodeBlock code={text} language="svg" /></div>;
}

'use client';

import { useContext } from 'react';
import { AtIcon } from '../_shared/icons';
import { Button } from '@/components/ui/button';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { RowReferenceContext, columnNames } from './row-reference';
import type { CodeViewProps } from './svg-view';

/** Rows of a CSV text (comma or semicolon separated, double-quoted cells with `""` escapes), at most 2000. */
export function csvRows(text: string): string[][] {
  const rows: string[][] = []; let row: string[] = [], cell = '', quoted = false;
  for (let i = 0; i < text.length && rows.length < 2000; i++) {
    const c = text[i];
    if (quoted) { if (c === '"' && text[i + 1] === '"') { cell += '"'; i++; } else if (c === '"') quoted = false; else cell += c; }
    else if (c === '"') quoted = true;
    else if (c === ',' || c === ';') { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
    else cell += c;
  }
  if ((cell || row.length) && rows.length < 2000) { row.push(cell); rows.push(row); }
  return rows;
}

/** A CSV artifact as a table: the first row is the header. Inside a `RowReferenceContext` each row has an « @ » action that references it in the assistant. */
export function CsvView({ text }: CodeViewProps) {
  const [head = [], ...rows] = csvRows(text);
  const target = useContext(RowReferenceContext);
  const names = columnNames(head);
  return <Table data-testid="artifact-csv">
    <TableHeader><TableRow>{head.map((cell, i) => <TableHead key={i}>{cell}</TableHead>)}{target && <TableHead className="w-10"><span className="sr-only">{target.label}</span></TableHead>}</TableRow></TableHeader>
    <TableBody>{rows.map((row, i) => <TableRow key={i} className="group/row" data-row={i + 1}>
      {row.map((cell, j) => <TableCell key={j} className="align-top">{cell}</TableCell>)}
      {target && <TableCell className="align-middle">
        <Button type="button" variant="ghost" size="icon-sm" data-testid="csv-row-reference" aria-label={`${target.label} ${i + 1}`}
          className="pointer-fine:opacity-0 pointer-fine:group-hover/row:opacity-100 pointer-fine:group-focus-within/row:opacity-100 focus-visible:opacity-100"
          onClick={() => target.reference({ path: target.path, row: i + 1, cells: Object.fromEntries(names.map((name, j) => [name, row[j] ?? ''])) })}><AtIcon aria-hidden="true" /></Button>
      </TableCell>}
    </TableRow>)}</TableBody>
  </Table>;
}

'use client';

import { createContext } from 'react';
import { AtIcon } from '../_shared/icons';
import type { MentionKind } from '../pi-chat/config';

/** One row of a table file, as the assistant receives it: the file, the row's number (the first row under the header is 1) and its cells by column. */
export interface RowReference {
  readonly path: string;
  readonly row: number;
  readonly cells: Readonly<Record<string, string>>;
}

/** What a table view needs to offer "reference this row": where the file is, the action's words and what a choice does. Absent: the table has no action. */
export interface RowReferenceTarget {
  readonly path: string;
  readonly label: string;
  readonly reference: (row: RowReference) => void;
}
export const RowReferenceContext = createContext<RowReferenceTarget | null>(null);

/** The mention prefix of a row reference: `@row:<path>#<row> <cells as JSON>` (a value with spaces is written in quotes, as any mention is). */
export const ROW_MENTION = 'row';
const VALUE = /^(.+?)#(\d+) (\{.*\})$/s;

/** A header row's names, each made unique so two columns called alike keep both cells. */
export function columnNames(head: readonly string[]): string[] {
  const seen = new Map<string, number>();
  return head.map((cell, at) => {
    const name = cell.trim() || `column ${at + 1}`;
    const count = (seen.get(name) ?? 0) + 1;
    seen.set(name, count);
    return count === 1 ? name : `${name} (${count})`;
  });
}

/** The mention's value, without its `row:` prefix: what `MentionKind.label` receives and what the assistant parses back. */
export const rowReferenceValue = ({ path, row, cells }: RowReference): string => `${path}#${row} ${JSON.stringify(cells)}`;
/** The `@` mention text for a row reference, prefix included, ready for `mentionToken`. */
export const rowMentionPath = (reference: RowReference): string => `${ROW_MENTION}:${rowReferenceValue(reference)}`;

/** The reference a mention value (without its prefix) stands for; undefined when it is not a well-formed row reference. */
export function parseRowReference(value: string): RowReference | undefined {
  const match = VALUE.exec(value);
  if (!match) return undefined;
  try {
    const cells = JSON.parse(match[3]!) as unknown;
    if (typeof cells !== 'object' || cells === null || Array.isArray(cells) || !Object.values(cells).every(cell => typeof cell === 'string')) return undefined;
    return { path: match[1]!, row: Number(match[2]), cells: cells as Record<string, string> };
  } catch { return undefined; }
}

/** The chip's short words: « open-gaps.csv row 3: Card Harbor Garage, Jan 09 ». */
export function rowReferenceLabel(value: string): string {
  const reference = parseRowReference(value);
  if (!reference) return value;
  const file = reference.path.split('/').at(-1) ?? reference.path;
  const first = Object.values(reference.cells).filter(cell => cell.trim() !== '').slice(0, 2).join(', ');
  return `${file} row ${reference.row}${first ? `: ${first}` : ''}`;
}

/** The composer's chip and the sent message's mention for a row reference. The shell adds it to an app's `mentions.kinds` as `row`. */
export const rowMentionKind: MentionKind = {
  label: rowReferenceLabel,
  icon: <AtIcon className="size-4" aria-hidden="true" />,
};
